## 运动会分数统计

**输入约定。** 第一行输入 `n m w`；随后输入恰好 `m+w` 个项目。每个项目先输入 `eventNo take`（`take` 只能为 3 或 5），再按名次从 1 到 `take` 输入 `name schoolNo result`。姓名和成绩均是不含空格的字符串；项目 `1..m` 计入男子，项目 `m+1..m+w` 计入女子。遇到重复项目号、非法学校号、项目数越界或读入不足立即报错并退出。

```c
typedef struct { int event, rank, point; char name[64], result[64]; } Award;
typedef struct { Award a[250]; int cnt, male, female; } School;
static int point(int take,int rank) {
    static const int p5[]={7,5,3,2,1}, p3[]={5,3,2};
    return take==5 ? p5[rank-1] : p3[rank-1];
}
/* school[1..n] 清零，seen[1..m+w] 清零后执行。 */
int ReadAndAccumulate(int n,int m,int w,School school[],bool seen[]) {
  for (int i=0;i<m+w;i++) {
    int e,t; if (scanf("%d%d",&e,&t)!=2 || e<1 || e>m+w || seen[e] || (t!=3&&t!=5)) return 0;
    seen[e]=true;
    for (int r=1;r<=t;r++) {
      char name[64],result[64]; int s;
      if (scanf("%63s%d%63s",name,&s,result)!=3 || s<1 || s>n || school[s].cnt==250) return 0;
      Award *x=&school[s].a[school[s].cnt++];
      x->event=e; x->rank=r; x->point=point(t,r);
      strcpy(x->name,name); strcpy(x->result,result);
      if (e<=m) school[s].male+=x->point; else school[s].female+=x->point;
    }
  }
  return 1;
}
```

读入成功后，按学校号逐一输出 `a[0..cnt-1]` 中的“项目号、名次、姓名、成绩、得分”，再输出 `male`、`female` 和二者之和；所有 `cnt=0` 的学校也输出零分。每条获奖记录恰属于一个学校，且按项目号只累加到一个性别栏，故报表总分等于成绩单各项得分之和。

**可复验样例。** 对 `n=4,m=3,w=2`，令奇数项目取 5 名、偶数项目取 3 名；项目 1 的学校号依次为 `1,2,3,4,1`，项目 2 为 `2,3,4`，项目 3 为 `4,1,2,3,4`，项目 4 为 `3,1,2`，项目 5 为 `2,3,4,1,2`。应得团体表：学校 1 为 `(男子13,女子5,总18)`，2 为 `(13,10,23)`，3 为 `(8,10,18)`，4 为 `(12,3,15)`。总获奖记录数为 R 时，读入、汇总和输出时间为 `O(m+w+R)`，空间为 `O(R)`。

## 约瑟夫环

使用**不设头结点的单向循环链表**。结点存 `id,password,next`，尾指针 `tail` 的后继始终是当前第一人。输入 `n,m` 和 n 个密码；要求 `1<=n<=30`、`m>0` 且密码均为正数，否则不建立环并报错。

```c
typedef struct Node { int id,password; struct Node *next; } Node;
int Joseph(Node **tail,int n,int m) {
  if (!tail || !*tail || n<1 || m<1) return 0;
  Node *pre=*tail;                 /* pre->next 是本轮从 1 开始报数者 */
  while (n) {
    int step=(m-1)%n;
    while (step--) pre=pre->next;
    Node *out=pre->next;
    printf("%d%c",out->id,n==1?'\n':' ');
    m=out->password;
    if (out==pre) { free(out); *tail=NULL; return 1; }
    pre->next=out->next;
    if (out==*tail) *tail=pre;
    free(out); --n;
  }
  return 1;
}
```

建表时按编号 1 到 n 尾插；若 `malloc` 失败，释放已建结点并失败返回。循环不变式为：`pre->next` 正是本轮报数起点，链表仍按未出列者的顺时针次序相连。前移 `(m-1)%n` 次后，其后继恰为第 m 个报数者；摘链后又从该人的顺时针后继开始，故过程与题意一致。

**样例。** 密码为 `3,1,7,2,4,8,4`，首轮按题面取 `m=6`，输出必须为 `6 1 4 7 2 3 5`。若使用题面出现的 `m=20`，首轮按取模仍为第 6 人。建环时间和空间均为 `O(n)`；逐轮数人最坏为 `O(n^2)`，除链表外额外空间 `O(1)`。

## 集合的并、交和差

集合用按字符升序、无重复的单链表表示。读入一整行字符串，仅接纳 `a..z`；数字、空格和其他字符忽略。先用 `seen[26]` 去重，再按字母顺序尾插，保证三个运算都能作一次归并扫描。

```c
typedef struct SNode { char ch; struct SNode *next; } SNode;
SNode *New(char c){ SNode *p=malloc(sizeof *p); if(p){p->ch=c;p->next=NULL;} return p; }
SNode *Build(const char *s){
  bool seen[26]={0}; for(;*s;s++) if(*s>='a'&&*s<='z') seen[*s-'a']=true;
  SNode *h=NULL,**tail=&h; for(int i=0;i<26;i++) if(seen[i]) { if(!(*tail=New('a'+i))) { Free(h); return NULL;} tail=&(*tail)->next; } return h;
}
SNode *Merge(SNode *a,SNode *b,int mode){ /* mode: 1并，2交，3差 */
  SNode *r=NULL,**tail=&r;
  while(a||b){ char x; int put=0;
    if(!b||(a&&a->ch<b->ch)){x=a->ch;put=mode!=2;a=a->next;}
    else if(!a||b->ch<a->ch){x=b->ch;put=mode==1;b=b->next;}
    else {x=a->ch;put=mode!=3;a=a->next;b=b->next;}
    if(put){ if(!(*tail=New(x))){Free(r);return NULL;} tail=&(*tail)->next; }
  } return r;
}
```

`Free` 从表头逐结点释放；分配失败时先释放已生成结果并报告失败，两个操作数均不改动。指针只向后移动：并集相等时只放入一次，交集只放入相等元素，差集只放入只在第一个集合出现的元素，所以输出仍有序且无重复。

**样例。** `magazine` 和 `paper` 分别建为 `[a,e,g,i,m,n,z]`、`[a,e,p,r]`；并、交、差依次为 `[a,e,g,i,m,n,p,r,z]`、`[a,e]`、`[g,i,m,n,z]`。`012oper4a6tion89` 与 `error data` 的结果依次为 `[a,d,e,i,n,o,p,r,t]`、`[a,e,o,r,t]`、`[i,n,p]`。若两表长度为 p、q，建表为 `O(|输入|+26)`，每种运算时间为 `O(p+q)`、结果空间为 `O(p+q)`。

## 长整数加法

以**带头结点的循环双向链表**表示万进制长整数：头结点 `tag` 的符号表示正负、绝对值表示组数；`next` 到 `prior` 为高位到低位，普通结点的 `group` 在 `0..9999`。零唯一规范化为一个值为 0 的结点，且 `tag=1`。字符串输入可带正负号和逗号：去逗号后首组 1 至 4 位，后续组必须恰 4 位；任一非法字符或格式错误拒绝输入。

```c
#define BASE 10000
LongInt AddAbs(LongInt a,LongInt b){
  LongInt r=NewHead(); DNode *p=a->prior,*q=b->prior; int carry=0,cnt=0;
  while(p!=a||q!=b||carry){
    int s=carry+(p!=a?p->group:0)+(q!=b?q->group:0);
    InsertAfterHead(r,s%BASE); carry=s/BASE; ++cnt;
    if(p!=a)p=p->prior; if(q!=b)q=q->prior;
  } r->tag=cnt; return r;
}
LongInt Add(LongInt a,LongInt b){
  int sa=Sign(a),sb=Sign(b); LongInt r;
  if(sa==sb){r=AddAbs(a,b);SetSign(r,sa);}
  else if(CompareAbs(a,b)>=0){r=SubAbs(a,b);SetSign(r,sa);}
  else {r=SubAbs(b,a);SetSign(r,sb);}
  NormalizeZero(r); return r;
}
```

`SubAbs(big,small)` 与 `AddAbs` 同样从 `prior` 向前扫描，借位时加 BASE，最后删去多余最高零组但保留唯一零组。`CompareAbs` 先比绝对组数，再逐组比较。`InsertAfterHead` 使从低到高算出的组仍按高到低保存；`NewHead`、插入失败或解析失败均释放临时链表并返回错误。算法只读 a、b，结果另建，故不会破坏操作数；最大中间和 `9999+9999+1=19999`，未超 32767。

**样例。** `-2345,6789 + -7654,3211 = -1,0000,0000`；`-9999,9999 + 1,0000,0000,0000 = 9999,0000,0001`；`1,0001,0001 + -1,0001,0001 = 0`。输出时负数先印 `-`，首组不补零，其余组以四位补零。两数有 p、q 组时，比较、加减、输出均为 `O(p+q)`，结果空间为 `O(max(p,q))`，没有位数上限。

## 一元稀疏多项式计算器

用带头结点的单链表保存多项式。头结点 `terms` 是实际非零项数；元素结点为 `(coef,exp)`，按指数严格降序。输入采用 `n,c1,e1,...,cn,en`；要求 `n>=0`、系数为有限实数、指数为整数。输入项可无序且可同指数：每项调用 `InsertTerm` 合并，绝对值不大于 `EPS` 的系数立即删除，因此零多项式仅有头结点且 `terms=0`。

```c
typedef struct PolyNode { int terms,exp; double coef; struct PolyNode *next; } PolyNode,*Poly;
const double EPS=1e-10;
int InsertTerm(Poly h,double c,int e){
  if(fabs(c)<=EPS)return 1; PolyNode *pre=h,*p=h->next;
  while(p&&p->exp>e){pre=p;p=p->next;}
  if(p&&p->exp==e){ p->coef+=c; if(fabs(p->coef)<=EPS){pre->next=p->next;free(p);--h->terms;} return 1;}
  PolyNode *x=malloc(sizeof *x); if(!x)return 0;
  x->terms=0;x->coef=c;x->exp=e;x->next=p;pre->next=x;++h->terms;return 1;
}
Poly AddOrSub(Poly a,Poly b,int signB){
  Poly r=NewPolyHead(); if(!r)return NULL; PolyNode *p=a->next,*q=b->next;
  while(p||q){ int ok;
    if(!q||(p&&p->exp>q->exp)){ok=InsertTerm(r,p->coef,p->exp);p=p->next;}
    else if(!p||q->exp>p->exp){ok=InsertTerm(r,signB*q->coef,q->exp);q=q->next;}
    else {ok=InsertTerm(r,p->coef+signB*q->coef,p->exp);p=p->next;q=q->next;}
    if(!ok){Destroy(r);return NULL;}
  } return r;
}
```

加法调用 `AddOrSub(a,b,+1)`，减法调用 `AddOrSub(a,b,-1)`；输入表只读，结果表另建。循环不变式是结果已含两个指针之前所有指数的正确和或差，且无重复指数和零项，扫描结束即为结果。输出先印 `terms`，再输出 `(coef,exp)` 对；数学格式要省略非零指数项的系数 1，并正确处理首项和负号。

**样例。** `(2x+5x^8-3.1x^11)+(7-5x^8+11x^9)` 输出 `-3.1x^11+11x^9+2x+7`；`(x+x^3)+(-x-x^3)` 输出 `0`；`(x+x^100)+(x^100+x^200)` 输出 `x+2x^100+x^200`。任意序建表最坏 `O(n^2)`、已降序输入为 `O(n)`；两表有 p、q 项时加减为 `O(p+q)`，结果空间 `O(p+q)`。

## 池塘夜降彩色雨

每个雨点是链表中的动态结点，生命周期为有限状态机：`FALL`（下落）、`SPLASH`（落水声）和 `RIPPLE`（同心圆扩散）。结点记录随机生成的 x、初始 y、水面 y、颜色、最大半径、当前半径、状态和下一次更新时间。`DrawDrop`、`DrawCircle`、`PlaySplash` 是图形/声音平台适配函数；核心状态机与数据管理可单文件运行于任意提供这些回调的窗口循环。

```c
typedef enum { FALL,SPLASH,RIPPLE } State;
typedef struct Drop { int x,y,waterY,color,maxR,r; unsigned long next; State st; struct Drop *nextNode; } Drop;
bool Advance(Drop *d,unsigned long now){
  if(d->st==FALL){ d->y+=FALL_SPEED; if(d->y<d->waterY){DrawDrop(d->x,d->y,d->color);d->next=now+FALL_TICK;} else {d->y=d->waterY;d->st=SPLASH;d->next=now;} }
  else if(d->st==SPLASH){ PlaySplash(d->x,d->waterY,d->color);d->st=RIPPLE;d->r=1;d->next=now+RIPPLE_TICK; }
  else { DrawCircle(d->x,d->waterY,d->r,d->color);d->r+=RIPPLE_STEP; if(d->r>d->maxR)return true; d->next=now+RIPPLE_TICK; }
  return false;
}
void Tick(Drop **head,unsigned long now){
  for(Drop **pp=head;*pp;){ Drop *d=*pp; if(now>=d->next&&Advance(d,now)){*pp=d->nextNode;free(d);} else pp=&d->nextNode; }
}
```

主循环维护 `nextBirth`：当 `now>=nextBirth` 时创建一个雨点，设置 `nextBirth=now+Rand(minGap,maxGap)`，再调用 `Tick` 并重绘背景与所有存活结点。要求 `minGap>0`、各随机区间下界不大于上界、窗口尺寸和水面范围有效；`malloc` 失败时跳过本次生成但不破坏现有链表。通过指向指针 `pp` 删除，可保证相邻到期雨点不被跳过。

**可复验时序。** 若某雨点在 `t=0` 出生、`waterY=10`、初始 `y=8`、`FALL_SPEED=1`、`FALL_TICK=10`、`maxR=3`、`RIPPLE_STEP=1`，则 t=10 画 y=9，t=20 转入 SPLASH，t=20 播放声音并置半径 1，随后画半径 1、2、3，下一次更新后删除。每个存活结点恰处于一个状态且 `next` 是其下次变化时刻，故可并发管理多个雨点。每帧更新时间为 `O(k)`、空间为 `O(k)`，k 为当前存活雨点数。
